```javascript
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, smoothstep, uv, time, pow, sin, fract, float, uniform, normalize, dot, abs, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'prism-refraction-node';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#101017';
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.6, hex: '#12121a' },
    { at: 1, hex: '#16161d' }
  ];

  const accent = new THREE.Color(accentHex);
  const paper = new THREE.Color(paperHex);
  const cool = new THREE.Color('#9fb0c4');

  const c0 = new THREE.Color(stops[0].hex);
  const c1 = new THREE.Color(stops[1]?.hex ?? '#12121a');
  const c2 = new THREE.Color(stops[2]?.hex ?? '#16161d');
  const t1 = stops[1]?.at ?? 0.6;

  // ---- Backdrop with engineered gradient ----
  const backdropMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  const vCoord = uv().y;
  const gradCol = mix(mix(vec3(c0), vec3(c1), smoothstep(float(0.0), float(t1), vCoord)), vec3(c2), smoothstep(float(t1), float(1.0), vCoord));

  // Radial accent glow centered behind prism
  const cx = uv().x.sub(0.5);
  const cy = uv().y.sub(0.52);
  const radialDist = cx.mul(cx).add(cy.mul(cy)).sqrt();
  const accentGlow = smoothstep(float(0.30), float(0.0), radialDist).mul(0.18);

  // Vignette
  const vignette = float(1.0).sub(smoothstep(float(0.35), float(0.95), radialDist)).mul(0.85).add(0.15);

  // Cool light wash from upper-left
  const washFactor = smoothstep(float(0.85), float(0.0), uv().x.add(uv().y.mul(0.5))).mul(0.06);
  const coolWash = vec3(cool).mul(washFactor);

  // Subtle grain
  const noiseSeed = uv().x.mul(117.0).add(uv().y.mul(83.0));
  const noiseVal = fract(sin(noiseSeed).mul(43758.5453)).sub(0.5).mul(0.02);

  backdropMat.colorNode = gradCol
    .mul(vignette)
    .add(vec3(accent).mul(accentGlow))
    .add(coolWash)
    .add(noiseVal);

  const backdrop = new THREE.Mesh(new THREE.PlaneGeometry(8, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---- Closer glow plane behind prism ----
  const glowMat = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
  });
  const glowRadial = uv().sub(0.5).length();
  glowMat.colorNode = vec3(accent).mul(0.55).add(vec3(cool).mul(0.45));
  glowMat.opacityNode = smoothstep(float(0.45), float(0.0), glowRadial).mul(0.10);
  const glowPlane = new THREE.Mesh(new THREE.PlaneGeometry(5, 4), glowMat);
  glowPlane.position.set(0, 0, -1.8);
  group.add(glowPlane);

  // ---- Glass prism ----
  const sideLen = 1.2;
  const prismLength = 1.8;
  const triRadius = sideLen / Math.sqrt(3); // ~0.693
  const prismGeo = new THREE.CylinderGeometry(triRadius, triRadius, prismLength, 3, 1, false);
  prismGeo.rotateZ(Math.PI / 2); // axis along X (horizontal)

  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color(paperHex),
    attenuationDistance: 2.5,
    side: THREE.DoubleSide,
    transparent: true,
  });

  // TSL dispersion + iridescence fringe
  const nL = normalize(normalLocal);
  const vDir = normalize(positionLocal);
  const fresnel = float(1.0).sub(abs(dot(nL, vDir)));
  const dispAmount = float(0.18);
  const shimmer = sin(time.mul(0.5).add(positionLocal.y.mul(3.0))).mul(0.04);
  const tDisp = fresnel.mul(dispAmount).add(shimmer);
  const dispTint = mix(
    vec3(1.0, 0.82, 0.78),
    vec3(0.78, 0.86, 1.0),
    smoothstep(float(0.0), float(0.5), tDisp)
  );
  const irisR = sin(time.mul(0.3).add(fresnel.mul(8.0))).add(1.0).mul(0.5);
  const irisG = sin(time.mul(0.3).add(fresnel.mul(8.0)).add(2.094)).add(1.0).mul(0.5);
  const irisB = sin(time.mul(0.3).add(fresnel.mul(8.0)).add(4.188)).add(1.0).mul(0.5);
  const iridescentFringe = vec3(irisR, irisG, irisB).mul(pow(fresnel, float(1.5))).mul(0.3);
  prismMat.emissiveNode = iridescentFringe.add(dispTint.mul(fresnel).mul(0.12));
  prismMat.colorNode = mix(vec3(1.0), dispTint, fresnel.mul(0.25));

  const prismMesh = new THREE.Mesh(prismGeo, prismMat);
  prismMesh.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
  prismMesh.position.set(0, 0, 0);
  group.add(prismMesh);

  // ---- Emissive core octahedron ----
  const coreGeo = new THREE.OctahedronGeometry(0.35, 0);
  const coreMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(accentHex),
    roughness: 0.35,
    metalness: 0.1,
    transparent: true,
  });
  coreMat.emissiveNode = vec3(accent).mul(2.2);
  const core = new THREE.Mesh(coreGeo, coreMat);
  core.position.set(0, 0, 0);
  group.add(core);

  const coreTL = gsap.timeline({ repeat: -1, yoyo: true });
  coreTL.to(core.scale, { x: 1.08, y: 1.08, z: 1.08, duration: 2.4, ease: 'sine.inOut' });

  // ---- Caustic streak on floor ----
  const causticMat = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
  });
  const cauU = uv().x;
  const cauFade = smoothstep(float(0.0), float(0.15), cauU).mul(smoothstep(float(1.0), float(0.85), cauU));
  const cauColor = mix(
    mix(vec3(accent), vec3(paper), smoothstep(float(0.2), float(0.5), cauU)),
    vec3(cool),
    smoothstep(float(0.5), float(0.8), cauU)
  );
  const cauVert = smoothstep(float(0.5), float(0.0), abs(uv().y.sub(0.5)).mul(2.0));
  causticMat.colorNode = cauColor;
  causticMat.opacityNode = cauFade.mul(cauVert).mul(0.35);
  const caustic = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 0.5), causticMat);
  caustic.position.set(0, -1.1, 0.1);
  caustic.rotation.x = -Math.PI / 2;
  group.add(caustic);

  // ---- Contact shadow ----
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const shadowRadial = uv().sub(0.5).length();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(float(0.5), float(0.0), shadowRadial).mul(0.5);
  const shadowPlane = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 1.2), shadowMat);
  shadowPlane.position.set(0, -1.05, -0.2);
  shadowPlane.rotation.x = -Math.PI / 2;
  group.add(shadowPlane);

  // ---- Lights ----
  // Back rim: strong cool directional from behind-left
  const rimLight = new THREE.DirectionalLight(0x9fb0c4, 1.4);
  rimLight.position.set(-2.8, 1.5, -2.5);
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  // Accent rim from behind-right
  const accentRim = new THREE.DirectionalLight(accent.getHex(), 0.8);
  accentRim.position.set(2.5, -0.5, -2.0);
  accentRim.target.position.set(0, 0, 0);
  group.add(accentRim);
  group.add(accentRim.target);

  // Key fill from front-left (low intensity to preserve contrast)
  const keyFill = new THREE.DirectionalLight(0xe8ecf2, 0.5);
  keyFill.position.set(-1.5, 1.0, 3.0);
  keyFill.target.position.set(0, 0, 0);
  group.add(keyFill);
  group.add(keyFill.target);

  // Ambient
  const ambient = new THREE.AmbientLight(0x9fb0c4, 0.4);
  group.add(ambient);

  // ---- Text ----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  for (const item of textItems) {
    if (item.role === 'headline') {
      const h = ctx.fontAtlas.createText(item.text, {
        fontSize: 68,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 68 * (-0.005),
      });
      h.position.set(0, -1.75, 0.2);
      group.add(h);
      textMeshes.push(h);
    } else if (item.role === 'caption') {
      const c = ctx.fontAtlas.createText(item.text, {
        fontSize: 18,
        color: '#9fb0c4',
        align: 'center',
        letterSpacingPx: 18 * 0.08,
      });
      c.position.set(0, -2.25, 0.2);
      group.add(c);
      textMeshes.push(c);
    }
  }

  // ---- Entrance animation ----
  const entranceTL = gsap.timeline();
  group.scale.set(0.96, 0.96, 0.96);
  group.userData.visible = false;
  entranceTL.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.7, ease: 'power3.out' });
  entranceTL.from(prismMesh.rotation, { y: prismMesh.rotation.y + 0.3, duration: 0.9, ease: 'power2.out' }, 0);

  // ---- Cinematic primitives ----
  const primCleanups = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    if (prim.name === 'depth-rotate' && ctx.primitives['depth-rotate']) {
      const result = ctx.primitives['depth-rotate'](prismMesh, prim.params ?? { maxDeg: 10 });
      if (result && result.cleanup) primCleanups.push(result.cleanup);
    } else if (ctx.primitives[prim.name]) {
      const result = ctx.primitives[prim.name](prismMesh, prim.params ?? {});
      if (result && result.cleanup) primCleanups.push(result.cleanup);
    }
  }

  // ---- Handlers ----
  group.userData.handlers = {
    click: () => {
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    coreTL.kill();
    entranceTL.kill();
    for (const c of primCleanups) {
      try { c(); } catch (e) { /* noop */ }
    }
    backdropMat.dispose();
    glowMat.dispose();
    prismMat.dispose();
    coreMat.dispose();
    causticMat.dispose();
    shadowMat.dispose();
    prismGeo.dispose();
    coreGeo.dispose();
    backdrop.geometry.dispose();
    glowPlane.geometry.dispose();
    caustic.geometry.dispose();
    shadowPlane.geometry.dispose();
  };

  return group;
}
